import React, { useState } from 'react';
import { FileText, X } from 'lucide-react';
import { twMerge } from 'tailwind-merge';
import {
  THEME_DROPZONE_ACTIVE,
  THEME_TEXT_COLORS,
  type ThemeVariant,
} from '../theme/variants';

export interface FileDropzoneProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'title'> {
  file: File | null;
  onFileChange: (file: File | null) => void;
  acceptedFormats?: string;
  title?: string;
  description?: string;
  variant?: ThemeVariant;
  className?: string;
  children?: React.ReactNode;
}

interface DropzoneContentProps {
  file: File | null;
  title: string;
  description: string;
  highlightClass: string;
  onClearFile: () => void;
}

const DropzoneContent: React.FC<DropzoneContentProps> = ({
  file,
  title,
  description,
  highlightClass,
  onClearFile,
}) => (
  <>
    <FileText className="w-8 h-8 text-slate-400 mx-auto" />
    <div className="text-xs text-slate-300 font-medium">
      {file ? (
        <div className="inline-flex items-center space-x-2 bg-card px-3 py-1 rounded-lg border border-border">
          <span className={`${highlightClass} font-semibold truncate max-w-[240px]`}>
            {file.name}
          </span>
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onClearFile();
            }}
            className="text-slate-400 hover:text-slate-200 p-0.5 rounded"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      ) : (
        <>
          <span>{title.split('browse')[0]}</span>
          <span className={`${highlightClass} underline`}>browse</span>
          <span>{title.split('browse')[1] || ''}</span>
        </>
      )}
    </div>
    <p className="text-[10px] text-slate-500">{description}</p>
  </>
);

export const FileDropzone: React.FC<FileDropzoneProps> = ({
  file,
  onFileChange,
  acceptedFormats = '.pdf,.csv',
  title = 'Drop your file here, or browse',
  description = 'Supports official PDF and CSV documents',
  variant = 'amber',
  className = '',
  children,
  ...rest
}) => {
  const [dragActive, setDragActive] = useState(false);
  const inputId = React.useId();

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onFileChange(e.dataTransfer.files[0]);
    }
  };

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileChange(e.target.files[0]);
    }
  };

  const activeBorder = THEME_DROPZONE_ACTIVE[variant] || THEME_DROPZONE_ACTIVE.amber;
  const highlightClass = THEME_TEXT_COLORS[variant] || THEME_TEXT_COLORS.amber;

  return (
    <div
      {...rest}
      onDragEnter={handleDrag}
      onDragOver={handleDrag}
      onDragLeave={handleDrag}
      onDrop={handleDrop}
      className={twMerge(
        'border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all',
        dragActive
          ? activeBorder
          : 'border-border hover:border-slate-600 bg-background/50',
        className
      )}
    >
      <input
        type="file"
        accept={acceptedFormats}
        id={inputId}
        onChange={handleFileInput}
        className="hidden"
      />
      <label htmlFor={inputId} className="cursor-pointer space-y-2 block">
        <DropzoneContent
          file={file}
          title={title}
          description={description}
          highlightClass={highlightClass}
          onClearFile={() => onFileChange(null)}
        />
      </label>

      {children && <div className="mt-4">{children}</div>}
    </div>
  );
};
