import React from 'react';
import { twMerge } from 'tailwind-merge';
import { THEME_SEGMENT_ACTIVE, type ThemeVariant } from '../theme/variants';

export interface SegmentedControlOption<T extends string = string> {
  id: T;
  label: string;
  icon?: React.ReactNode;
  badge?: string | number;
}

export interface SegmentedControlProps<T extends string = string>
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options: SegmentedControlOption<T>[];
  value: T;
  onChange: (value: T) => void;
  variant?: ThemeVariant;
  size?: 'xs' | 'sm' | 'md';
  fullWidth?: boolean;
  className?: string;
  idPrefix?: string;
}

const sizeStyles = {
  xs: 'px-2.5 py-1 text-xs',
  sm: 'px-3 py-1.5 text-xs',
  md: 'px-3.5 py-2 text-sm',
};

export function SegmentedControl<T extends string = string>({
  options,
  value,
  onChange,
  variant = 'amber',
  size = 'xs',
  fullWidth = false,
  className = '',
  idPrefix = 'segmented',
  style,
  ...rest
}: SegmentedControlProps<T>) {
  const activeClass = THEME_SEGMENT_ACTIVE[variant] || THEME_SEGMENT_ACTIVE.amber;
  const sizeClass = sizeStyles[size] || sizeStyles.xs;

  return (
    <div
      role="tablist"
      className={twMerge(
        'inline-flex items-center bg-card/60 p-0.5 rounded-ui-control border border-border',
        fullWidth && 'w-full grid',
        className
      )}
      style={
        fullWidth
          ? { ...style, gridTemplateColumns: `repeat(${options.length}, minmax(0, 1fr))` }
          : style
      }
      {...rest}
    >
      {options.map((option) => {
        const isSelected = value === option.id;
        return (
          <button
            key={option.id}
            role="tab"
            aria-selected={isSelected}
            type="button"
            data-testid={`${idPrefix}-${option.id}`}
            onClick={() => onChange(option.id)}
            className={`font-medium rounded-ui-control border transition-all duration-150 flex items-center justify-center gap-1.5 ${sizeClass} ${
              isSelected
                ? `${activeClass} font-semibold`
                : 'border-transparent text-muted hover:text-foreground hover:bg-card-muted/60'
            }`}
          >
            {option.icon && <span className="shrink-0">{option.icon}</span>}
            <span>{option.label}</span>
            {option.badge !== undefined && (
              <span className="text-[10px] px-1.5 py-0.2 rounded-full bg-slate-800 text-slate-300 font-mono">
                {option.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}
